import React from "react"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"
import { Typography } from "@/components/atoms/text/Typography"
import { StackV } from "@/components/frames/Stack"

/**
 * STORYBOOK-LOCAL DESIGN SPEC ΓÇö TitledText: a primary line + optional muted
 * secondary (and optional hint) stacked vertically as ONE composite. A
 * "title<->subtitle" pair is a semantic UNIT, so it is a single component (one
 * anatomy node), NOT two/three raw `<Typography>` hand-rolled at every row.
 *
 * This is the single most-recurring composite in the app (ΓëÑ16 call-sites, ΓëÑ6
 * lanes: SettingToggleRow, ListRow, Stepper, PageHeader, EmptyState,
 * RewardItemCard, PersonaIdentityChip name/role, SummaryCard statΓÇª). The
 * composite OWNS the type scale per `size`; the caller passes nodes only.
 * NO `@/components` imports.
 */

/**
 * Vertical text-stack scale:
 * - `row`    ΓÇö dense list/setting row (title `sm` medium ┬╖ subtitle `xs` muted).
 * - `header` ΓÇö section/page header (title `h3` semibold ┬╖ subtitle `sm` muted).
 * - `stat`   ΓÇö a metric (title = big `h3` bold VALUE ┬╖ subtitle = foreground label ┬╖ hint muted).
 */
export type TitledTextSize = "row" | "header" | "stat"

/** Typography `size` + tone config resolved per {@link TitledTextSize}. */
/**
 * Skeleton bar width per line. Named so the widths can be typed where they are WRITTEN, not
 * only where they are read: the classes must be literal (`w-1/2`) because Tailwind only emits
 * a class it can see as a literal string in the source.
 */
interface TitledTextSkeletonWidths {
    /** Width class of the title bar. */
    title: AllowedClassName
    /** Width class of the subtitle bar. */
    sub: AllowedClassName
    /** Width class of the hint bar. */
    hint: AllowedClassName
}

interface SizeConfig {
    titleSize: "sm" | "h3"
    titleWeight: "medium" | "semibold" | "bold"
    subSize: "xs" | "sm"
    /** `undefined` -> foreground (default); `"muted"` -> muted line. */
    subColor?: "muted"
    subWeight?: "medium"
    /**
     * Skeleton bar width for each line ΓÇö write the class LITERALLY (`w-1/2`), don't
     * build it dynamically (`w-${ΓÇª}`), since Tailwind only generates a class from a
     * literal string it scans in the source.
     */
    skeleton: TitledTextSkeletonWidths
}

const SIZE_CONFIG: Record<TitledTextSize, SizeConfig> = {
    row: {
        titleSize: "sm",
        titleWeight: "medium",
        subSize: "xs",
        subColor: "muted",
        skeleton: { title: "w-1/2", sub: "w-2/3", hint: "w-1/3" }},
    header: {
        titleSize: "h3",
        titleWeight: "semibold",
        subSize: "sm",
        subColor: "muted",
        skeleton: { title: "w-1/3", sub: "w-2/3", hint: "w-1/2" }},
    stat: {
        titleSize: "h3",
        titleWeight: "bold",
        // stat's secondary is the LABEL ΓÇö foreground + medium, not muted.
        subSize: "sm",
        subWeight: "medium",
        skeleton: { title: "w-1/3", sub: "w-2/3", hint: "w-1/2" }}}

/** Props for the {@link TitledText} composite. */
export interface TitledTextProps {
    /** Primary line (title / name / label / stat value), rendered through `Typography`. */
    title: string
    /** Optional secondary line beneath the title (subtitle / role / description / stat label). */
    subtitle?: string
    /** Optional third muted line (only meaningful for `size="stat"`, e.g. a delta hint). */
    hint?: string
    /** Text-stack scale. Defaults to `"row"`. */
    size?: TitledTextSize
    /** Override the title weight (per-size default otherwise). */
    weight?: "medium" | "semibold" | "bold"
    /** Truncate every line to a single line (needs a bounded parent width). */
    truncate?: boolean
    /** `true` -> render the skeleton mirror (bars sized per line). */
    isSkeleton?: boolean
    /**
     * Where this sits inside its parent. Appearance is not passable ΓÇö it is already a prop.
     */
    classNames?: Array<AllowedClassName>
}

/**
 * TitledText renders a primary line over an optional muted secondary (and hint)
 * as one vertical unit. The composite OWNS the type scale + tone per `size`; the
 * caller passes nodes only. Root is `flex min-w-0 flex-col` so truncation works
 * and callers can add `flex-1`.
 *
 * @param props - {@link TitledTextProps}
 */
/** Source-level tier metadata ΓÇö see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "TitledText" } as const

/** Renders a primary line over an optional muted subtitle and hint as one vertical unit. */
export const TitledText = ({
    title,
    subtitle,
    hint,
    size = "row",
    weight,
    truncate = false,
    isSkeleton = false,
    classNames,
}: TitledTextProps) => {
    const cfg = SIZE_CONFIG[size]
    const rootClassNames: Array<AllowedClassName> = ["min-w-0", ...(classNames ?? [])]

    // COMPOSITE-10: ONE render path ΓÇö same `StackV`, same `gap`, in both states.
    // Text always goes through the `Typography` ATOM; `isSkeleton` just flows
    // straight into it so each line draws its own bar, sized to its own value
    // (┬º12c) ΓÇö no second, hand-built skeleton tree to keep in sync with this one.
    return (
        <StackV
            gap={1}
            classNames={rootClassNames}
            items={[
                () => (
                    <Typography
                        size={cfg.titleSize}
                        weight={isSkeleton ? undefined : (weight ?? cfg.titleWeight)}
                        truncate={isSkeleton ? undefined : truncate}
                        isSkeleton={isSkeleton}
                        classNames={isSkeleton ? [cfg.skeleton.title] : undefined}
                        text={title}
                    />
                ),
                ...(subtitle ? [() => (
                    <Typography
                        size={cfg.subSize}
                        color={isSkeleton ? undefined : cfg.subColor}
                        weight={isSkeleton ? undefined : cfg.subWeight}
                        truncate={isSkeleton ? undefined : truncate}
                        isSkeleton={isSkeleton}
                        classNames={isSkeleton ? [cfg.skeleton.sub] : undefined}
                        text={subtitle}
                    />
                )] : []),
                ...(hint ? [() => (
                    <Typography
                        size="xs"
                        color={isSkeleton ? undefined : "muted"}
                        truncate={isSkeleton ? undefined : truncate}
                        isSkeleton={isSkeleton}
                        classNames={isSkeleton ? [cfg.skeleton.hint] : undefined}
                        text={hint}
                    />
                )] : []),
            ]}
        />
    )
}

import React from "react"
import { ArrowRightIcon, ShoppingCartIcon } from "@phosphor-icons/react"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { DrawerShell } from "@/components/composites/layout/DrawerShell"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"
import { Button } from "@/components/atoms/buttons/Button"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH, StackV } from "@/components/frames/Stack"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { PriceTagInline } from "@/components/blocks/commerce/PriceTag"
import { ProgressMeter } from "@/components/composites/stats/ProgressMeter"
import { CartLine } from "@/components/blocks/commerce/CartLine"
import type { CartItemEntity } from "@/modules/api/graphql/queries/types/my-cart"
import type { CoursesCheckoutPreviewLine } from "@/modules/api/graphql/queries/types/courses-checkout-preview"

/** All display text, already localized by the connected `MiniCartDrawer`; a story passes i18n keys. */
export interface MiniCartDrawerLabels {
    /** `"${cart.title} ┬╖ ${cart.itemsCount}"`, already interpolated with `count`. */
    header: string
    emptyTitle: string
    emptyDescription: string
    browseCourses: string
    errorTitle: string
    retry: string
    /** `cart.comboActive`/`cart.comboStart`, already picked+interpolated for the current `bundlePercent`. */
    comboLabel: string
    /** `cart.bundleBonus`, already interpolated ΓÇö only shown while `bundlePercent > 0`. */
    bundleBonusChip: string
    /** `cart.comboNextHint`/`cart.comboMaxHint`, already picked+interpolated for `nextTierPercent`. */
    comboHint: string
    total: string
    /** `cart.savings`, already interpolated ΓÇö only shown while `savingsVnd > 0`. */
    savings: string
    /** `cart.installmentHint`, already interpolated ΓÇö only shown while `cheapestMonthlyVnd` is set. */
    installmentHint: string
    checkout: string
    viewFullCart: string
}

/** Props for {@link _MiniCartDrawer} ΓÇö presentational; all data resolved, no fetch/store/i18n. */
export interface MiniCartDrawerProps {
    isOpen: boolean
    onOpenChange: (open: boolean) => void
    /** Slide-in edge. `true` on mobile ΓåÆ bottom sheet. */
    isMobile: boolean
    /** First load, nothing in hand ΓåÆ the cart-list zone shimmers in place (co-located). */
    isSkeleton?: boolean
    /** Settled with zero lines ΓåÆ the empty message replaces the list. */
    isEmpty?: boolean
    /** Truthy ΓåÆ the cart-list zone falls to the error message (beats loading + empty). */
    error?: unknown
    onRetry?: () => void
    onBrowseCourses?: () => void
    items?: Array<CartItemEntity>
    /** courseId ΓåÆ the real checkout-preview line, for per-line pricing. */
    previewByCourse?: Map<string, CoursesCheckoutPreviewLine>
    isMutating?: boolean
    onRemove: (courseId: string) => void
    /** Combo-meter fill (0..3). */
    itemCount?: number
    /** Whether the current bundle tier is above zero ΓÇö gates the bonus chip. */
    bundlePercent?: number
    /** First load of the checkout preview, cart already settled ΓåÆ the footer summary shimmers. */
    isPreviewSkeleton?: boolean
    /** The real checkout preview ΓÇö total/savings/installments. `undefined` while pending or on error. */
    preview?: { totalChargedVnd: number; totalListVnd: number; savingsVnd: number }
    /** `true` ΓåÆ the preview fetch settled with an error; falls back to `fallbackTotalVnd`. */
    previewError?: boolean
    /** Sum of entity display prices ΓÇö shown only when the preview failed to load. */
    fallbackTotalVnd?: number
    /** Cheapest installment monthly amount, already formatted. `null` ΓåÆ no installment plans exist. */
    cheapestMonthlyLabel?: string | null
    onCheckout?: () => void
    onViewFullCart?: () => void
    labels: MiniCartDrawerLabels
}

/**
 * Mini-cart drawer ΓÇö the presentational half of {@link _MiniCartDrawer}'s connected
 * `MiniCartDrawer` (`index.tsx`): the slide-out cart confirmation + combo meter,
 * right on desktop / bottom-sheet on mobile. Composed on `DrawerShell` (the shared
 * panel-scaffold composite): a nested `SurfaceCardList` reusing {@link CartLine}
 * (the SAME row the `/cart` page uses), a bundle-discount `ProgressMeter`, and a
 * footer with the real charged total + saving, a primary "Checkout" and a text
 * link to the full cart page. `error`/`isEmpty` fall to the shared
 * `AsyncContentError` / `AsyncContentEmpty` composites; otherwise the tree renders
 * with `isSkeleton` threaded down so the shimmer mirrors the loaded shape
 * (loading-and-skeleton.md). See `tiers/split.md` ΓÇö the connected `index.tsx` owns
 * the fetch, the stores, and the i18n.
 *
 * @param props - {@link MiniCartDrawerProps}
 */
export const _MiniCartDrawer = ({
    isOpen,
    onOpenChange,
    isMobile,
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    onBrowseCourses,
    items = [],
    previewByCourse,
    isMutating = false,
    onRemove,
    itemCount = 0,
    bundlePercent = 0,
    isPreviewSkeleton = false,
    preview,
    previewError = false,
    fallbackTotalVnd = 0,
    cheapestMonthlyLabel = null,
    onCheckout,
    onViewFullCart,
    labels,
}: MiniCartDrawerProps) => {
    const comboLabelRow = [
        () => <Typography size="sm" weight="medium" isSkeleton={isSkeleton} text={labels.comboLabel} />,
        ...(isSkeleton
            ? [() => <Chip isSkeleton tone="accent" />]
            : bundlePercent > 0
                ? [() => <Chip tone="accent" text={labels.bundleBonusChip} />]
                : []),
    ]
    const comboMeterItems = [
        () => (
            <StackH
                gap={3}
                principle="flex-action"
                explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                align="center"
                justify="between"
                items={comboLabelRow}
            />
        ),
        () => <ProgressMeter value={itemCount} max={3} isSkeleton={isSkeleton} />,
        () => <Typography size="xs" color="muted" isSkeleton={isSkeleton} text={labels.comboHint} />,
    ]
    const comboMeterSection: ComponentTypeWithSkeleton = () => (
        <StackV gap={3} items={comboMeterItems} />
    )

    // Line list ΓÇö reuses the SAME `CartLine` as the `/cart` page. `variant="nested"`:
    // this list is NESTED inside the drawer surface, where `shadow-surface` renders
    // invisible against the parent (dark mode) ΓÇö nested cards need a border to
    // delineate (`card.md` ┬ºsurface-in-surface). The `/cart` PAGE keeps the default
    // surface variant (top-level on `bg-background`, shadow shows). `CartLine` has no
    // co-located skeleton of its own, so the loading rows are mirrored by hand,
    // same shape (leading tile ┬╖ two text lines ┬╖ trailing action).
    const cartLineSkeletonItems = [
        () => <Skeleton className="size-12 shrink-0 rounded-xl" />,
        () => (
            <StackV
                gap={3}
                classNames={["min-w-0", "flex-1"]}
                items={[
                    () => <Skeleton className="h-4 w-1/2 rounded-lg" />,
                    () => <Skeleton className="h-4 w-24 rounded-lg" />,
                ]}
            />
        ),
        () => <Skeleton className="size-9 shrink-0 rounded-lg" />,
    ]
    const cartListSection: ComponentTypeWithSkeleton = () => {
        const listItems: Array<SurfaceCardListItem> = isSkeleton
            ? Array.from({ length: 2 }, (_row, index) => ({
                key: `skeleton-${index}`,
                content: () => (
                    <StackH
                        gap={4}
                        principle="content-row"
                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                        align="center"
                        items={cartLineSkeletonItems}
                    />
                ),
            }))
            : items.map((item) => ({
                key: item.id,
                content: () => (
                    <CartLine
                        item={item}
                        previewLine={previewByCourse?.get(item.courseId)}
                        onRemove={onRemove}
                        isMutating={isMutating}
                    />
                ),
            }))
        return (
            <SurfaceCardList
                variant="nested"
                items={listItems}
                isSkeleton={isSkeleton}
            />
        )
    }

    // Body ΓÇö error ΓåÆ skeleton ΓåÆ empty ΓåÆ content (BLOCK-8): the empty and error
    // surfaces are the shared `AsyncContent*` composites dropped in as their own
    // states; otherwise the ONE tree renders, with `isSkeleton` threaded down so
    // the shimmer mirrors the loaded shape.
    const cartBody: ComponentTypeWithSkeleton = () => {
        if (error) {
            return <AsyncContentError title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retry} />
        }
        if (!isSkeleton && isEmpty) {
            return (
                <AsyncContentEmpty
                    icon={ShoppingCartIcon}
                    title={labels.emptyTitle}
                    description={labels.emptyDescription}
                    onRetry={onBrowseCourses}
                    retryLabel={labels.browseCourses}
                />
            )
        }
        return <StackV gap={6} isSkeleton={isSkeleton} items={[comboMeterSection, cartListSection]} />
    }

    const previewSkeletonTotalRow = [
        () => <Skeleton className="h-5 w-20 rounded-lg" />,
        () => <Skeleton className="h-7 w-32 rounded-lg" />,
    ]
    const totalPriceRow = [
        () => <Typography size="base" weight="semibold" text={labels.total} />,
        ...(preview
            ? [() => (
                <PriceTagInline
                    discounted={preview.totalChargedVnd}
                    original={preview.totalListVnd}
                    currency="VND"
                />
            )]
            // preview failed to load ΓÇö fall back to the plain list
            // total (no bundle discount known) so the total is never blank.
            : previewError
                ? [() => <PriceTagInline discounted={fallbackTotalVnd} currency="VND" />]
                : []),
    ]
    const totalSummaryItems = [
        () => (
            <StackH
                gap={4}
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                align="center"
                items={totalPriceRow}
            />
        ),
        ...(preview && preview.savingsVnd > 0
            ? [() => <Typography size="sm" color="success-soft" text={labels.savings} />]
            : []),
        ...(cheapestMonthlyLabel != null
            ? [() => <Typography size="xs" color="muted" text={labels.installmentHint} />]
            : []),
    ]
    const footerItems = [
        () => (
            isPreviewSkeleton ? (
                <StackH
                    gap={4}
                    principle="content-row"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                    align="center"
                    items={previewSkeletonTotalRow}
                />
            ) : (
                <StackV gap={2} items={totalSummaryItems} />
            )
        ),
        () => (
            <Button
                variant="primary"
                size="lg"
                suffixIcon={ArrowRightIcon}
                isDisabled={isMutating}
                onPress={onCheckout}
                label={labels.checkout}
                classNames={["w-full"]}
            />
        ),
        () => (
            <Button
                variant="tertiary"
                onPress={onViewFullCart}
                label={labels.viewFullCart}
                classNames={["w-full"]}
            />
        ),
    ]
    const footerSection: ComponentTypeWithSkeleton = () => (
        <StackV gap={4} items={footerItems} />
    )

    return (
        <DrawerShell
            isOpen={isOpen}
            onOpenChange={onOpenChange}
            placement={isMobile ? "bottom" : "right"}
            title={labels.header}
            dialogWidth="cart"
            footerVariant="stacked"
            isSkeleton={isSkeleton}
            body={cartBody}
            footer={items.length > 0 ? footerSection : undefined}
            identity={{ tier: "overlay", component: "MiniCartDrawer" }}
        />
    )
}

import React, { useEffect, useMemo, useState } from "react"
import { SparkleIcon } from "@phosphor-icons/react"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { AsyncContentEmpty } from "@/components/composites/async/AsyncContent"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { EnumChip, type EnumChipEntry } from "@/components/composites/chips/EnumChip"
import { DrawerShell } from "@/components/composites/layout/DrawerShell"
import { InlineIconLabel } from "@/components/composites/text/InlineIconLabel"
import { Pagination } from "@/components/atoms/navigation/Pagination"
import { StackH, StackV } from "@/components/frames/Stack"
import { useSmViewpoint } from "@/hooks/reuseables/useSmViewpoint"
import type { AiModelCategory } from "@/modules/api/graphql/queries/query-ai-models"

/** Attempts per page inside the history drawer. */
const HISTORY_PAGE_SIZE = 6

/** Accessible name for the pager `<nav>` ΓÇö `Pagination` already owns its own internal `aria-label`. */
const PAGER_ARIA_LABEL = "Task attempt history pagination"

/** One history row, already resolved by the connected `PersonalProjectTaskResultHistoryDrawer` ΓÇö no raw entity. */
export interface PersonalProjectTaskResultHistoryRow {
    id: string
    /** Drives the verdict chip tone (comes straight off `attempt.passed`, no threshold math). */
    passed: boolean
    score: number | null
    servedModel: string | null
    category?: AiModelCategory
    /** `t("submissionAttempts.attemptLine", { number })`, already interpolated. */
    attemptLineLabel: string
    /** Relative time (`getTimeAgoLabel`), already localized ΓÇö `null` when the attempt has no `processedAt`. */
    timeLabel: string | null
}

/** All display text, already localized by the connected `PersonalProjectTaskResultHistoryDrawer`; a story passes i18n keys. */
export interface PersonalProjectTaskResultHistoryDrawerLabels {
    /** Bare drawer title (`t("personalProjectResult.history")`) ΓÇö the row count is appended alongside it. */
    historyLabel: string
    passed: string
    failed: string
    /** Empty-state title (no attempts yet). */
    emptyTitle: string
    /** Empty-state secondary line. Optional. */
    emptyDescription?: string
}

/** Props for {@link _PersonalProjectTaskResultHistoryDrawer} ΓÇö presentational; all data resolved, no fetch/store/i18n. */
export type PersonalProjectTaskResultHistoryDrawerProps = {
    /** Whether the drawer is open. */
    isOpen: boolean
    /** Open/close callback (also closes when a row is selected). */
    onOpenChange: (open: boolean) => void
    /** Full attempt list (newest first), already resolved to display rows. */
    rows: Array<PersonalProjectTaskResultHistoryRow>
    /** Currently selected attempt (highlighted row). */
    selectedAttemptId?: string
    /** Task max score (for the `x/max` label); 0 ΓåÆ show bare score. */
    maxScore: number
    /** Select an attempt (the page navigates `?attempt=`). */
    onSelect: (attemptId: string) => void
    labels: PersonalProjectTaskResultHistoryDrawerLabels
    /** AI-model tier ΓåÆ chip presentation, already localized ΓÇö the model-byline recipe (`EnumChip`). */
    categoryMap: Partial<Record<AiModelCategory, EnumChipEntry>>
}

/** `x/max` when `maxScore` is set, otherwise the bare score. `null` reads as `0`. */
const scoreLabel = (score: number | null, maxScore: number) => (maxScore > 0 ? `${score ?? 0}/${maxScore}` : `${score ?? 0}`)

/**
 * One row's free-form content: attempt line + verdict chip + score on the first line
 * (score pushed to the far edge), an optional model byline (sparkle + model name +
 * tier chip) + time-ago on the second. Mirrors the sibling `SubmissionAttemptsDrawer`
 * row recipe ΓÇö the model byline is composed here from `InlineIconLabel` + `EnumChip`
 * instead of the `ModelByline` block, since this tier may only import composites/frames.
 */
const attemptRowContent = (
    row: PersonalProjectTaskResultHistoryRow,
    isSelected: boolean,
    maxScore: number,
    labels: PersonalProjectTaskResultHistoryDrawerLabels,
    categoryMap: Partial<Record<AiModelCategory, EnumChipEntry>>,
) => {
    const servedModel = row.servedModel
    const category = row.category
    const timeLabel = row.timeLabel

    const attemptLabelAndChip = [
        () => <Typography size="sm" weight="medium" text={row.attemptLineLabel} />,
        () => <Chip tone={row.passed ? "success" : "danger"} text={row.passed ? labels.passed : labels.failed} />,
    ]

    const attemptLine = [
        () => <StackH gap={2} principle="chip-row" align="center" items={attemptLabelAndChip} explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."/>,
        () => (
            <Typography
                size="sm"
                color={row.passed ? "success-soft" : "muted"}
                text={scoreLabel(row.score, maxScore)}
            />
        ),
    ]

    const bylineParts = [
        ...(servedModel != null ? [() => (
            <InlineIconLabel icon={SparkleIcon} tone="default" size="xs" label={servedModel} />
        )] : []),
        ...(servedModel != null && category != null ? [() => (
            <EnumChip value={category} map={categoryMap} />
        )] : []),
    ]

    const rowContent = [
        () => <StackH gap={3} principle="sibling-stack" align="center" justify="between" items={attemptLine} explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."/>,
        ...(bylineParts.length > 0 || timeLabel != null ? [() => (
            <StackH
                gap={3}
                principle="sibling-stack"
                explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                align="center"
                justify="between"
                items={[
                    ...(bylineParts.length > 0 ? [() => <StackH gap={3} principle="sibling-stack" explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups." align="center" items={bylineParts} />] : []),
                    ...(timeLabel != null ? [() => <Typography size="xs" color="muted" text={timeLabel} />] : []),
                ]}
            />
        )] : []),
    ]

    // highlight-exception (mirrors `SubmissionAttemptsDrawer`): the selected row's tint is
    // baked into the row's own content wrapper ΓÇö a plain, un-tightened `<div>` ΓÇö since
    // `SurfaceCardListItem` no longer takes a raw `className` of its own.
    return (
        <div className={isSelected ? "bg-accent-soft" : undefined}>
            <StackV gap={2} items={rowContent} />
        </div>
    )
}

/**
 * Personal-project task submission-history drawer ΓÇö the presentational half of
 * {@link PersonalProjectTaskResultHistoryDrawer}: each attempt as a free-form
 * `SurfaceCardList` row (verdict, score, the AI model that graded it + tier, time),
 * paginated client-side. Right on desktop, bottom sheet on mobile. Sibling of
 * `SubmissionResultHistoryDrawer` (challenge) ΓÇö here the verdict comes straight from
