    return (
        <DrawerShell
            identity={{ tier: "overlay", component: "PersonalProjectTaskResultHistoryDrawer" }}
            isOpen={isOpen}
            onOpenChange={onOpenChange}
            placement={isMobile ? "bottom" : "right"}
            title={`${labels.historyLabel} ┬╖ ${rows.length}`}
            body={() => <StackV gap={4} items={listAndPager} />}
        />
    )
