    /** Accessible name for the remove control. */
    remove: string
    /** Fallback title shown when a pin has none. */
    untitled: string
}

const PinnedProjectMeta = ({ pin, labels }: Pick<PinnedProjectCardProps, "pin" | "labels">) => (
    <Cluster
        gap={2}
        items={[
            ...(pin.isVerified ? [() => (
                <StatusChip
                    tone="success"
                    icon={VerifiedIcon}
                >
                    {labels.verified}
                </StatusChip>
            )] : []),
            ...(pin.techStack ?? []).map((tech) => () => (
                <Chip key={tech} tone="default" text={tech} />
            )),
        ]}
    />
)

const PinnedProjectManageFooter = ({
    pin,
    canMoveUp,
    canMoveDown,
    isBusy,
    onMoveUp,
    onMoveDown,
    onRemove,
    labels,
}: Omit<PinnedProjectCardProps, "manage">) => (
    <Cluster
        gap={2}
        items={[
            () => (
                <Button
                    size="sm"
                    variant="secondary"
                    isIconOnly
                    isDisabled={isBusy || !canMoveUp}
                    ariaLabel={labels.moveUp}
                    prefixIcon={CaretUpIcon}
                    onPress={() => onMoveUp?.(pin.id)}
                />
            ),
            () => (
                <Button
                    size="sm"
                    variant="secondary"
                    isIconOnly
                    isDisabled={isBusy || !canMoveDown}
                    ariaLabel={labels.moveDown}
                    prefixIcon={CaretDownIcon}
                    onPress={() => onMoveDown?.(pin.id)}
                />
            ),
            ...(pin.url ? [() => (
                <Button
                    size="sm"
                    variant="secondary"
                    isIconOnly
                    ariaLabel={labels.open}
                    prefixIcon={ExternalLinkIcon}
                    onPress={() => window.open(pin.url as string, "_blank", "noopener,noreferrer")}
                />
            )] : []),
            () => (
                <Button
                    size="sm"
                    variant="danger"
                    isIconOnly
                    isPending={isBusy}
                    ariaLabel={labels.remove}
                    prefixIcon={TrashIcon}
                    onPress={() => onRemove?.(pin.id)}
                />
            ),
        ]}
    />
)

/** Props for {@link PinnedProjectCard}. */
export interface PinnedProjectCardProps {
    /** The pinned project to render (list-item data prop ΓÇö store can't index it). */
    pin: QueryUserPinnedProjectItem
    /**
     * Owner-only management mode. When true the card renders move/remove controls
     * instead of behaving as a plain outbound link.
     */
    manage?: boolean
    /** Whether the move-up control is enabled (false for the first pin). */
    canMoveUp?: boolean
    /** Whether the move-down control is enabled (false for the last pin). */
    canMoveDown?: boolean
    /** True while a mutation touching this pin is in flight (disables controls). */
    isBusy?: boolean
    /** Move this pin one slot earlier. */
    onMoveUp?: (id: string) => void
    /** Move this pin one slot later. */
    onMoveDown?: (id: string) => void
    /** Remove this pin. */
    onRemove?: (id: string) => void
    /** Already-translated strings ΓÇö see {@link PinnedProjectCardLabels}. */
    labels: PinnedProjectCardLabels
}

/**
 * Presentational card for a single pinned project. In display mode the whole
 * card is an outbound link (when the pin has a URL); in `manage` mode it exposes
 * reorder + remove controls. Built on the {@link MediaCard} block ΓÇö title via
 * {@link MediaCard}'s own `title` slot, tech stack as {@link Chip} atoms, and a
 * success-toned "Verified by StarCi" {@link StatusChip} for verified course pins.
 *
 * Pure list-item: receives its `pin` + callbacks + already-translated
 * {@link PinnedProjectCardLabels} from the parent, holds no store and calls no `t()`.
 *
 * @param props - {@link PinnedProjectCardProps}
 */
export const PinnedProjectCard = ({
    pin,
    manage = false,
    canMoveUp = false,
    canMoveDown = false,
    isBusy = false,
    onMoveUp,
    onMoveDown,
    onRemove,
    labels,
}: PinnedProjectCardProps) => {
    const hasMeta = pin.isVerified || (pin.techStack?.length ?? 0) > 0

    return (
        <MediaCard
            title={pin.title ?? labels.untitled}
            meta={hasMeta ? () => <PinnedProjectMeta pin={pin} labels={labels} /> : undefined}
            description={pin.description ?? undefined}
            footer={manage ? () => (
                <PinnedProjectManageFooter
                    pin={pin}
                    canMoveUp={canMoveUp}
                    canMoveDown={canMoveDown}
                    isBusy={isBusy}
                    onMoveUp={onMoveUp}
                    onMoveDown={onMoveDown}
                    onRemove={onRemove}
                    labels={labels}
                />
            ) : undefined}
            // display mode: the whole card is the outbound link (only when it has one)
            href={!manage && pin.url ? pin.url : undefined}
        />
    )
}

import React, { useState } from "react"
import { ModalShell } from "@/components/composites/layout/ModalShell"
import { Button } from "@/components/atoms/buttons/Button"
import { Tabs } from "@/components/atoms/navigation/Tabs"
import { Typography } from "@/components/atoms/text/Typography"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Box } from "@/components/frames/Box"
import { Cluster } from "@/components/frames/Cluster"
import { StackV } from "@/components/frames/Stack"
import { AsyncContentEmpty } from "@/components/composites/async/AsyncContent"
import { PinnedProjectCard, type PinnedProjectCardLabels } from "./PinnedProjectCard"
import { ExternalProjectForm } from "./ExternalProjectForm"
import { CourseProjectForm } from "./CourseProjectForm"
import type { QueryUserPinnedProjectItem } from "@/modules/api/graphql/queries/types/user-pinned-projects"

/** Tabs inside the manage-pinned-projects modal. */
type ManagePinsTab = "manage" | "external" | "course"

/** Rows shown while the owner's pinned list is first loading. */
const SKELETON_ROW_COUNT = 3
/** Icon-only footer actions a manage-mode card shows (move-up, move-down, open, remove). */
const SKELETON_BUTTON_COUNT = 4

/**
 * Loading mirror for the "manage" tab's pin list ΓÇö mirrors {@link PinnedProjectCard}'s
 * `MediaCard` shape (cover, title, meta chip row, description, and a 4-button
 * footer) row-for-row so the tab does not jump when data resolves. Co-located
 * right here (not a separate hand-kept file) since `PinnedProjectCard` takes
 * no `isSkeleton` prop of its own to thread through (`loading-and-skeleton.md`).
 */
const ManagePinnedListSkeleton = () => (
    <StackV
        gap={4}
        items={Array.from({ length: SKELETON_ROW_COUNT }).map(() => () => (
            <Box className="card">
                <StackV
                    gap={4}
                    items={[
                        () => <Skeleton className="aspect-video w-full rounded-xl" />,
                        () => <Skeleton.Typography width="1/2" />,
                        () => (
                            <Cluster
                                gap={3}
                                items={[
                                    () => <Skeleton.Chip />,
                                    () => <Skeleton.Chip />,
                                ]}
                            />
                        ),
                        () => <Skeleton.Typography type="body-sm" width="full" />,
                        () => <Skeleton.Typography type="body-sm" width="2/3" />,
                        () => (
                            <Cluster
                                gap={3}
                                items={Array.from({ length: SKELETON_BUTTON_COUNT }).map(() => () => (
                                    <Button isSkeleton isIconOnly size="sm" />
                                ))}
                            />
                        ),
                    ]}
                />
            </Box>
        ))}
    />
)

/** Already-translated strings {@link _ManagePinnedProjectsModal} renders ΓÇö resolved by the connected `ManagePinnedProjectsModal`, never `t()` itself. */
export interface ManagePinnedProjectsModalLabels {
    /** Modal header title. */
    manageTitle: string
    /** "Pinned" tab label ΓÇö already interpolated with the current count + {@link MAX_PINNED_PROJECTS}. */
    tabManage: string
    /** "External" tab label. */
    tabExternal: string
    /** "Course" tab label. */
    tabCourse: string
    /** Empty-state title shown when the owner has no pins yet. */
    emptyOwnerTitle: string
    /** Empty-state description shown when the owner has no pins yet. */
    emptyManage: string
    /** "You've reached the cap" banner ΓÇö already interpolated with {@link MAX_PINNED_PROJECTS}. */
    full: string
    /** Strings threaded to every {@link PinnedProjectCard}. */
    pinCard: PinnedProjectCardLabels
}

/** Props for {@link _ManagePinnedProjectsModal}. */
export interface ManagePinnedProjectsModalProps {
    /** Whether the modal is currently open. */
    isOpen: boolean
    /** Open-state change handler. */
    onOpenChange: (open: boolean) => void
    /** The signed-in owner's pinned projects (empty until loaded). */
    pins: Array<QueryUserPinnedProjectItem>
    /** `true` ΓåÆ first load, nothing in hand yet: the "Pinned" tab shows {@link ManagePinnedListSkeleton}. */
    isSkeleton?: boolean
    /** `true` ΓåÆ loading has finished and there are no pins: the "Pinned" tab shows the empty state. */
    isEmpty: boolean
    /** Whether the cap has been reached ΓÇö disables the "External"/"Course" tabs and shows the full banner. */
    isFull: boolean
    /** True while any unpin/reorder mutation is in flight. */
    isBusy: boolean
    /** Remove a pin by id. */
    onRemove: (id: string) => void
    /** Move a pin one slot earlier. */
    onMoveUp: (id: string) => void
    /** Move a pin one slot later. */
    onMoveDown: (id: string) => void
    /** Already-translated strings ΓÇö see {@link ManagePinnedProjectsModalLabels}. */
    labels: ManagePinnedProjectsModalLabels
}

/**
 * Owner-only modal to manage pinned projects: a "Pinned" tab listing the current
 * pins with reorder + remove controls, an "External" tab with the add-external
 * form, and a "Course" tab for capstone pins. Composes the shared `ModalShell`
 * dialog scaffold; the "External"/"Course" tabs render the CONNECTED
 * {@link ExternalProjectForm}/{@link CourseProjectForm} (each owns its own data ΓÇö
 * see `tiers/split.md`'s "a screen renders connected children" rule). Tab
 * selection is pure UI state, kept local to this presentational half.
 *
 * @param props - {@link ManagePinnedProjectsModalProps}
 */
export const _ManagePinnedProjectsModal = ({
    isOpen,
    onOpenChange,
    pins,
    isSkeleton = false,
    isEmpty,
    isFull,
    isBusy,
    onRemove,
    onMoveUp,
    onMoveDown,
    labels,
}: ManagePinnedProjectsModalProps) => {
    const [tab, setTab] = useState<ManagePinsTab>("manage")
    const backToManage = () => setTab("manage")

    const manageBody = isSkeleton ? (
        <ManagePinnedListSkeleton />
    ) : isEmpty ? (
        <AsyncContentEmpty
            title={labels.emptyOwnerTitle}
            description={labels.emptyManage}
        />
    ) : (
        <StackV
            gap={4}
            items={[
                ...(isFull ? [() => (
                    <Typography size="xs" color="muted" text={labels.full} />
                )] : []),
                ...pins.map((pin, index) => () => (
                    <PinnedProjectCard
                        key={pin.id}
                        pin={pin}
                        manage
                        isBusy={isBusy}
                        canMoveUp={index > 0}
                        canMoveDown={index < pins.length - 1}
                        onMoveUp={onMoveUp}
                        onMoveDown={onMoveDown}
                        onRemove={onRemove}
                        labels={labels.pinCard}
                    />
                )),
            ]}
        />
    )

    return (
        <ModalShell
            identity={{ tier: "overlay", component: "ManagePinnedProjectsModal" }}
            isOpen={isOpen}
            onOpenChange={onOpenChange}
            size="lg"
            title={labels.manageTitle}
            body={() => (
                <StackV
                    gap={5}
                    items={[
                        () => (
                            <Tabs
                                items={[
                                    { key: "manage", label: labels.tabManage },
                                    { key: "external", label: labels.tabExternal, isDisabled: isFull },
                                    { key: "course", label: labels.tabCourse, isDisabled: isFull },
                                ]}
                                selectedKey={tab}
                                onSelectionChange={(key) => setTab(key as ManagePinsTab)}
                                ariaLabel={labels.manageTitle}
                            />
                        ),
                        () => {
                            if (tab === "external") {
                                return <ExternalProjectForm onSuccess={backToManage} />
                            }
                            if (tab === "course") {
                                return <CourseProjectForm onSuccess={backToManage} />
                            }
                            return manageBody
                        },
                    ]}
                />
            )}
        />
    )
}

import { type SelectOption, SelectSingle } from "@/components/atoms/forms"
import React from "react"
import { ArrowRightIcon, GraduationCapIcon, LockIcon } from "@phosphor-icons/react"
import { ModalShell } from "@/components/composites/layout/ModalShell"
import { Toolbar } from "@/components/composites/navigation/Toolbar"
import { SurfaceCard, SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { AsyncContentError } from "@/components/composites/async/AsyncContent"
import { InlineIconLabel } from "@/components/composites/text/InlineIconLabel"
import { PriceTagProminent, PriceTagInline, type PriceCurrency } from "@/components/blocks/commerce/PriceTag"
import { IconTile } from "@/components/atoms/display/IconTile"
import { Typography, type TypographyIcon } from "@/components/atoms/text/Typography"
import { Button } from "@/components/atoms/buttons/Button"
import { Spinner } from "@/components/atoms/display/Spinner"

import { StackV, StackH } from "@/components/frames/Stack"
import { PaymentType } from "@/modules/types/enums/payment-type"

/**
 * `_PaymentModal` ΓÇö the SRC TWIN of the shared payment overlay: order summary
 * ("Summary" panel) then gateway pick ("Payment" panel), for every paid flow
 * (course enroll - multi-course checkout - membership - AI subscription).
 * Presentational: typed props, already resolved; no fetch/store/i18n (that's
 * the connected half, `./index.tsx`).
 *
 * Only the price region skeletons (`isSkeleton` flows into the order's
 * `PriceTagInline`/`PriceTagProminent` leaves only) ΓÇö the tabs, installment
 * picker, voucher field and gateway list render immediately, mirroring
 * `PremiumGateModal`'s own "only the price region rests" contract.
 */

/** Which of the modal's two panels is showing ΓÇö freely switchable, not a wizard. */
export type PaymentModalTab = "summary" | "payment"

/** One course row of the multi-course cart summary. */
export interface PaymentModalCheckoutLine {
    /** Stable row key (the course id). */
    key: string
    /** Course title. */
    title: string
    /** Course cover image, when known. */
    coverUrl?: string | null
    /** Real charged price in the active currency; `undefined` while its preview hasn't resolved. */
    discounted?: number | null
    /** List price in the active currency, struck through when it beats {@link PaymentModalCheckoutLine.discounted}. */
    original?: number | null
}

/** One loyalty-breakdown row ΓÇö WHY the discount applies (course flow only). */
export interface PaymentModalLoyaltyRow {
    /** Stable row key. */
    key: string
    /** Leading icon, a COMPONENT reference ΓÇö never already-built JSX. */
    icon: TypographyIcon
    /** Already-translated reason line. */
    label: string
}

/** One gateway inside {@link PaymentModalGatewayGroup}. */
export interface PaymentModalGatewayMethod {
    /** The gateway. */
    type: PaymentType
    /** Gateway display name (e.g. "PayOS"). */
    name: string
    /** Already-translated one-line description. */
    description: string
    /** Gateway logo. */
    iconUrl: string
    /** Amount charged through this gateway, already formatted; omitted while the price hasn't resolved. */
    amountLabel?: string
    /** `true` while a checkout through THIS gateway is in flight ΓÇö swaps the row's trailing arrow for a spinner. */
    isPending: boolean
}

/** The gateway group for the active currency (domestic VND <-> international USD). */
export interface PaymentModalGatewayGroup {
    /** Group label (e.g. "Domestic"). */
    label: string
    /** Currency tag shown beside the label (e.g. "VND"). */
    currencyLabel: string
    /** Gateways in this group, in display order. */
    methods: ReadonlyArray<PaymentModalGatewayMethod>
}

/** All display text, already localized by the connected `PaymentModal`; a story passes i18n keys. */
export interface PaymentModalLabels {
    title: string
    tabsAria: string
    tabSummary: string
    tabPayment: string
    continueToPayment: string
    total: string
    priceError: string
    membershipPrice: string
    installmentTitle: string
    payFull: string
    payInstallment: string
    /** "3 months" ΓÇö set only once a term is chosen. */
    installmentMonths?: string
    /** "ΓÇª/month" ΓÇö set only once a term is chosen. */
    installmentPerMonth?: string
    /** Total + markup summary line ΓÇö set only once a term is chosen. */
    installmentSummary?: string
    voucherTitle: string
    voucherNone: string
    voucherVndOnlyHint: string
    currencyVnd: string
    currencyUsd: string
    secure: string
    noCardStored: string
}

/** Props for {@link _PaymentModal} ΓÇö presentational; all data resolved, no fetch/store/i18n. */
export interface PaymentModalProps {
    /** Whether the modal is currently open. */
    isOpen: boolean
    /** Open/close callback. */
    onOpenChange: (open: boolean) => void

    /** Which panel is showing. */
    selectedTab: PaymentModalTab
    /** Fired when the learner switches panels (via the tab strip, or the "Continue" CTA). */
    onSelectedTabChange: (tab: PaymentModalTab) => void

    /** Product name (course title / cart count / AI tier / membership). */
    orderName: string
    /** Course cover for the single-item summary icon tile; omitted for every other flow. */
    orderCoverUrl?: string | null
    /** Multi-course cart lines; omitted for every single-product flow. */
    checkoutLines?: ReadonlyArray<PaymentModalCheckoutLine>

    /** The charged price (single-item summary, or the cart's charged total) in the active currency. */
    discounted?: number | null
    /** The list price, struck through when it beats {@link PaymentModalProps.discounted}. */
    original?: number | null
    /** Active-phase price before loyalty ΓÇö feeds the breakdown popover's middle step (course flow only). */
    phase?: number | null
    /** Loyalty discount percent (0 = no loyalty row). */
    discountPercent: number
    /** `true` -> no numeric price exists yet; shows the flat membership heading instead of a `PriceTag`. */
    isMembershipFlow: boolean
    /** Loyalty breakdown rows (course flow only); empty elsewhere. */
    loyaltyRows: ReadonlyArray<PaymentModalLoyaltyRow>

    /** Currency the summary price + gateway list are shown in. */
    currency: PriceCurrency
    /**
     * `true` -> the price region rests: only the `PriceTagInline`/`PriceTagProminent`
     * leaves shimmer, the rest of the panel (tabs, installment, voucher, gateways)
     * renders immediately.
     */
    isSkeleton?: boolean
    /** `true` -> the price region failed to load; replaces it with an error message. */
    priceError?: boolean

    /** `true` -> the "pay in full / pay in installments" picker shows (course flows with terms offered). */
    installmentAvailable: boolean
    /** `true` -> an installment term is the active plan (clamps the order to VND). */
    installmentActive: boolean
    /** Fired when the learner toggles between "pay in full" and "pay in installments". */
    onInstallmentActiveChange: (active: boolean) => void

    /** `true` -> the apply-voucher field shows (course flow, with applicable vouchers). */
    showVoucher: boolean
    /** Options for the apply-voucher field ΓÇö a leading "no voucher" row plus one per applicable voucher. */
    voucherOptions: Array<SelectOption>
    /** Applied voucher code, `null` = none. */
    voucherCode: string | null
    /** Fired when the learner picks a voucher (or clears it). */
    onVoucherCodeChange: (code: string | null) => void
    /** `true` -> the applied voucher is VND-only (clamps the order to the domestic side). */
    flatVoucherActive: boolean

    /** `true` -> international (USD) gateways are usable for this order ΓÇö the currency toggle shows. */
    hasUsd: boolean
    /** Fired when the learner switches the domestic/international currency. */
    onCurrencyChange: (currency: PriceCurrency) => void

    /** Gateways for the active currency; omitted only while no flow context is open. */
    activeGroup?: PaymentModalGatewayGroup
    /** Fired when the learner picks a gateway row. */
    onSelectMethod: (type: PaymentType) => void
    /** `true` while any checkout mutation is in flight ΓÇö disables every gateway row. */
    isMutating: boolean

    labels: PaymentModalLabels
}

/**
 * One course row of the multi-course cart summary ΓÇö icon tile, truncated title, and
 * (once resolved) its real charged price.
 */
const checkoutLineRow = (
    line: PaymentModalCheckoutLine,
    currency: PriceCurrency,
    isSkeleton: boolean,
) => (
    <StackH
        gap={4}
        principle="content-row"
        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
        align="center"
        items={[
            () => (
                <IconTile
                    size="sm"
                    tone="accent"
                    icon={GraduationCapIcon}
                    src={line.coverUrl}
                    alt={line.title}
                />
            ),
            () => (
                <Typography
                    size="sm"
                    truncate
                    classNames={["min-w-0", "flex-1"]}
                    text={line.title}
                />
            ),
            ...(isSkeleton || line.discounted != null
                ? [() => (
                    <PriceTagInline
                        discounted={line.discounted ?? 0}
                        original={line.original}
                        currency={currency}
                        isSkeleton={isSkeleton}
                        showSavingLine={false}
                    />
                )]
                : []),
        ]}
    />
)

/** The order summary panel ΓÇö a multi-course cart list + total, or a single-item price + loyalty breakdown. */
const summaryContent = (props: PaymentModalProps) => {
    const {
        orderName,
        orderCoverUrl,
        checkoutLines,
        discounted,
        original,
        phase,
        discountPercent,
        isMembershipFlow,
        loyaltyRows,
        currency,
        isSkeleton = false,
        priceError = false,
        labels,
        onSelectedTabChange,
    } = props

    if (priceError) {
        return <AsyncContentError title={labels.priceError} />
    }

    if (checkoutLines != null) {
        const checkoutLineItems = checkoutLines.map((line) => () => checkoutLineRow(line, currency, isSkeleton))
        const totalRow = [
            () => <Typography size="sm" weight="semibold" text={labels.total} />,
            ...(isSkeleton || discounted != null
                ? [() => (
                    <PriceTagProminent
                        discounted={discounted ?? 0}
                        original={original}
                        currency={currency}
                        isSkeleton={isSkeleton}
                        showSavingLine={false}
                    />
                )]
                : []),
        ]
        const checkoutSummaryItems = [
            () => <StackV gap={4} items={checkoutLineItems} />,
            () => (
                <StackH
                    gap={4}
                    principle="content-row"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                    justify="between"
                    items={totalRow}
                />
            ),
        ]
        return (
            <StackV
                gap={5}
                principle="group-boundary"
                explain="Section group spacing ΓÇö not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
                divider
                items={checkoutSummaryItems}
            />
        )
    }

    const priceRegion = isSkeleton || discounted != null
        ? (
            <PriceTagProminent
                discounted={discounted ?? 0}
                original={original}
                currency={currency}
                isSkeleton={isSkeleton}
                breakdown={phase != null ? { phase, loyaltyPercent: discountPercent } : undefined}
            />
        )
        : isMembershipFlow
            ? <Typography size="h4" weight="bold" text={labels.membershipPrice} />
            : null

    const orderIdentityItems = [
        () => (
            <IconTile
                size="sm"
                tone="accent"
                icon={GraduationCapIcon}
                src={orderCoverUrl}
                alt={orderName}
            />
        ),
        () => (
            <StackV
                gap={3}
                classNames={["min-w-0", "flex-1"]}
                items={[
                    () => <Typography size="xs" color="muted" truncate text={orderName} />,
                    () => priceRegion,
                ]}
            />
        ),
    ]

    const singleSummaryItems = [
        () => (
            <StackH
                gap={4}
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                align="center"
                items={orderIdentityItems}
            />
        ),
        ...(loyaltyRows.length > 0
            ? [() => (
                <StackV
                    gap={3}
                    items={loyaltyRows.map((row) => () => (
                        <InlineIconLabel icon={row.icon} label={row.label} tone="success" size="xs" />
                    ))}
                />
            )]
            : []),
        () => (
            <Button
                variant="primary"
                size="lg"
                suffixIcon={ArrowRightIcon}
                iconSlide
                classNames={["w-full"]}
                label={labels.continueToPayment}
                onPress={() => onSelectedTabChange("payment")}
            />
        ),
    ]

    return <StackV gap={4} items={singleSummaryItems} />
}

/** Trailing control for a gateway row - spinner while pending, else a chevron. */
interface GatewayTrailingProps {
    isPending: boolean
}

const GatewayTrailing = ({ isPending }: GatewayTrailingProps) => {
    if (isPending) {
        return <Spinner size="sm" />
    }
    return <ArrowRightIcon aria-hidden focusable="false" className="size-5 text-muted" />
}

/** One gateway row ΓÇö leading logo, name + description, amount, and a trailing arrow/spinner. */
const gatewayRow = (
    method: PaymentModalGatewayMethod,
    onSelectMethod: (type: PaymentType) => void,
    isMutating: boolean,
): SurfaceCardListItem => ({
    key: method.type,
    leading: () => (
        <img
            alt={method.name}
            className="h-8 w-12 shrink-0 object-contain object-left"
            src={method.iconUrl}
        />
    ),
    title: method.name,
    subtitle: method.description,
    metaText: method.amountLabel,
    trailing: () => <GatewayTrailing isPending={method.isPending} />,
    onPress: () => onSelectMethod(method.type),
    isDisabled: isMutating,
})

/** The payment panel ΓÇö installment picker, apply-voucher, currency toggle, gateway list, trust line. */
const paymentContent = (props: PaymentModalProps) => {
    const {
        installmentAvailable,
        installmentActive,
        onInstallmentActiveChange,
        showVoucher,
        voucherOptions,
        voucherCode,
        onVoucherCodeChange,
        flatVoucherActive,
        hasUsd,
        currency,
        onCurrencyChange,
        activeGroup,
        onSelectMethod,
        isMutating,
        labels,
    } = props

    const installmentMonthsRow = [
        () => <Typography size="sm" weight="semibold" text={labels.installmentMonths ?? ""} />,
        () => <Typography size="sm" color="muted" text={labels.installmentPerMonth ?? ""} />,
    ]

    const installmentSectionItems = [
        () => <Typography size="xs" weight="medium" color="muted" text={labels.installmentTitle} />,
        () => (
            <Toolbar
                variant="primary"
                size="sm"
                leftTabs={{
                    selectedKey: installmentActive ? "installment" : "full",
                    ariaLabel: labels.installmentTitle,
                    onSelectionChange: (key) => onInstallmentActiveChange(String(key) === "installment"),
                    items: [
                        { key: "full", label: labels.payFull },
                        { key: "installment", label: labels.payInstallment },
                    ],
                }}
            />
        ),
        ...(installmentActive && labels.installmentMonths != null
            ? [() => (
                <SurfaceCard
                    variant="nested"
                    padding={4}
                    body={() => (
                        <StackH
                            gap={4}
                            principle="content-row"
                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                            justify="between"
                            items={installmentMonthsRow}
                        />
                    )}
                />
            )]
            : []),
        ...(labels.installmentSummary != null
            ? [() => <Typography size="xs" color="muted" text={labels.installmentSummary ?? ""} />]
            : []),
    ]

    const voucherSectionItems = [
        () => (
            <SelectSingle
                label={labels.voucherTitle}
                ariaLabel={labels.voucherTitle}
                placeholder={labels.voucherNone}
                options={voucherOptions}
                value={voucherCode ?? ""}
                onValueChange={(value) => onVoucherCodeChange(value || null)}
                isDisabled={isMutating}
            />
        ),
        ...(flatVoucherActive
            ? [() => <Typography size="xs" color="muted" text={labels.voucherVndOnlyHint} />]
            : []),
    ]

    const trustLineItems = [
        () => <InlineIconLabel icon={LockIcon} label={labels.secure} size="xs" />,
        () => <Typography size="xs" color="muted" text={labels.noCardStored} />,
    ]

    const paymentPanelItems = [
        ...(installmentAvailable
            ? [() => <StackV gap={4} items={installmentSectionItems} />]
            : []),
        ...(showVoucher
            ? [() => <StackV gap={4} items={voucherSectionItems} />]
            : []),
        ...(hasUsd
            ? [() => (
                <Toolbar
                    variant="primary"
                    leftTabs={{
                        selectedKey: currency,
                        ariaLabel: labels.title,
                        onSelectionChange: (key) => onCurrencyChange(String(key) as PriceCurrency),
                        items: [
                            { key: "VND", label: labels.currencyVnd },
                            { key: "USD", label: labels.currencyUsd },
                        ],
                    }}
                />
            )]
            : []),
        ...(activeGroup
            ? [() => (
                <SurfaceCardList
                    label={activeGroup.label}
                    labelEnd={activeGroup.currencyLabel}
                    items={activeGroup.methods.map((method) => gatewayRow(method, onSelectMethod, isMutating))}
                />
            )]
            : []),
        () => (
            <StackV
                gap={3}
                principle="sibling-stack"
                explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                align="center"
                items={trustLineItems}
            />
        ),
    ]

    return <StackV gap={4} items={paymentPanelItems} />
}

/**
 * Shared payment modal for every paid flow. See the file header for the panel
 * layout and the `isSkeleton` contract.
 *
 * @param props - {@link PaymentModalProps}
 */
const _PaymentModal = (props: PaymentModalProps) => {
    const { isOpen, onOpenChange, selectedTab, onSelectedTabChange, labels } = props

    const body = () => (
        <StackV
            gap={6}
            items={[
                () => (
                    <Toolbar
                        leftTabs={{
                            selectedKey: selectedTab,
                            ariaLabel: labels.tabsAria,
                            onSelectionChange: (key) => onSelectedTabChange(String(key) as PaymentModalTab),
                            items: [
                                { key: "summary", label: labels.tabSummary },
                                { key: "payment", label: labels.tabPayment },
                            ],
                        }}
                    />
                ),
                () => (selectedTab === "summary" ? summaryContent(props) : paymentContent(props)),
            ]}
        />
    )

    return (
        <ModalShell
            isOpen={isOpen}
            onOpenChange={onOpenChange}
            title={labels.title}
            size="sm"
            body={body}
            identity={{ tier: "overlay", component: "PaymentModal" }}
        />
    )
}

export { _PaymentModal }

"use client"

import React, {
    useState,
} from "react"
import { Button, Chip, Typography, Spinner } from "@heroui/react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    SettingsBreadcrumb,
} from "@/components/blocks/settings/SettingsBreadcrumb"
import {
    EntityToken,
} from "@/components/blocks/entity/EntityToken"
import { useQueryMyMilestoneTaskAttemptsSwr, MY_MILESTONE_TASK_ATTEMPTS_LIMIT } from "@/hooks/swr/api/graphql/queries/useQueryMyMilestoneTaskAttemptsSwr"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { ListRow } from "@/components/blocks/lists/ListRow"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { StackV } from "@/components/frames/Stack"

/** Props for {@link MyAttemptsPage}. */
export type MyAttemptsPageProps = Record<string, never>
/**
 * The learner's milestone-task attempts as a list ΓÇö task, milestone, course,
 * pass/fail chip, score and date (failed attempts included). "Load more" grows
 * the page window via a single offset=0 query (`myMilestoneTaskAttempts`).
 *
 * @param props - optional root className.
 */
export const MyAttemptsPage = () => {
    const t = useTranslations()
    const locale = useLocale()

    /** How many pages have been requested (drives the growing window). */
    const [pageCount, setPageCount] = useState(1)

    const swr = useQueryMyMilestoneTaskAttemptsSwr(
        0,
        MY_MILESTONE_TASK_ATTEMPTS_LIMIT * pageCount,
    )
    const items = swr.data?.items ?? []
    const total = swr.data?.total ?? 0
    const hasMore = items.length < total

    const formatDate = (iso: string): string =>
        new Date(iso).toLocaleDateString(locale, {
            year: "numeric",
            month: "short",
            day: "numeric",
        })

    const listItems = [
        () => (
            <div className="flex flex-col gap-0">
                {items.map((item, index) => (
                    <ListRow
                        key={item.id}
                        title={item.taskTitle}
                        subtitle={item.milestoneTitle}
                        divider={index < items.length - 1}
                        meta={(
                            <>
                                <EntityToken
                                    globalId={item.courseGlobalId}
                                    label={item.courseTitle}
                                />
                                <Chip
                                    size="sm"
                                    variant="soft"
                                    color={item.passed ? "success" : "danger"}
                                >
                                    <Chip.Label>
                                        {item.passed
                                            ? t("profileSettings.learning.attempts.passed")
                                            : t("profileSettings.learning.attempts.failed")}
                                    </Chip.Label>
                                </Chip>
                                <Typography type="body-sm">
                                    {item.score}
                                </Typography>
                                <Typography type="body-xs" color="muted">
                                    {formatDate(item.attemptedAt)}
                                </Typography>
                            </>
                        )}
                    />
                ))}
            </div>
        ),
        ...(hasMore
            ? [() => (
                <div className="flex justify-center">
                    <Button
                        variant="ghost"
                        size="sm"
                        isDisabled={swr.isValidating}
                        onPress={() => setPageCount((count) => count + 1)}
                    >
                        {swr.isValidating ? (
                            <Spinner color="current" size="sm" />
                        ) : null}
                        {t("profileSettings.learning.loadMore")}
                    </Button>
                </div>
            )]
            : []),
    ]

    return (
        <div className={"flex flex-col gap-10"}>
            <PageHeader
                breadcrumb={<SettingsBreadcrumb current={t("profileSettings.learning.attempts.title")} />}
                title={t("profileSettings.learning.attempts.title")}
                description={t("profileSettings.learning.attempts.subtitle")}
            />

            <SurfaceCard
                label={t("profileSettings.learning.attempts.title")}

                body={() => (
                    <AsyncContent
                        isLoading={!swr.data && !swr.error}
                        skeleton={(
                            <StackV
                                gap={3}
                                principle="sibling-stack"
                                explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                items={[0, 1, 2].map((row) => () => (
                                    <Skeleton.ListRow key={row} withTrailing />
                                ))}
                            />
                        )}
                        isEmpty={items.length === 0}
                        emptyContent={{
                            title: t("profileSettings.learning.attempts.empty"),
                            description: t("profileSettings.learning.attempts.emptyHint"),
                        }}
                        error={!swr.data ? swr.error : undefined}
                        errorContent={{
                            title: t("profileSettings.learning.attempts.empty"),
                            onRetry: () => { void swr.mutate() },
                            retryLabel: t("profileSettings.learning.loadMore"),
                        }}
                    >
                        <StackV gap={4} items={listItems} />
                    </AsyncContent>
                )}
            />
        </div>
    )
}
